nsresult nsMsgDBView::FetchPriority(nsIMsgDBHdr* aHdr,
                                    nsAString& aPriorityString) {
  nsMsgPriorityValue priority = nsMsgPriority::notSet;
  aHdr->GetPriority(&priority);

  switch (priority) {
    case nsMsgPriority::highest:
      aPriorityString = *sHighestPriorityString;
      break;
    case nsMsgPriority::high:
      aPriorityString = *sHighPriorityString;
      break;
    case nsMsgPriority::low:
      aPriorityString = *sLowPriorityString;
      break;
    case nsMsgPriority::lowest:
      aPriorityString = *sLowestPriorityString;
      break;
    case nsMsgPriority::normal:
      aPriorityString = *sNormalPriorityString;
      break;
    default:
      break;
  }
